import typing

import pydantic

from ...schemas.rapi.base import BaseRapiResponseSchema


class Suggest(pydantic.BaseModel):
    type: typing.Optional[typing.Union[str, int]] = None
    sn: typing.Optional[typing.Union[str, int]] = None
    msgid: typing.Optional[typing.Union[str, int]] = None
    stickers: typing.Optional[list[str]] = None


class GetSuggestsResultsSchema(pydantic.BaseModel):
    suggests: list[Suggest]


class GetSuggestsResponseSchema(BaseRapiResponseSchema):
    results: GetSuggestsResultsSchema


class GetSmartReplyResultsSchema(pydantic.BaseModel):
    sticker_smartreply: list[str] = pydantic.Field(..., alias="sticker-smartreply")
    text_smartreply: list[str] = pydantic.Field(..., alias="text-smartreply")
    smart_hello: list[str] = pydantic.Field(..., alias="smart-hello")
    msgId: int


class GetSmartReplyResponseSchema(BaseRapiResponseSchema):
    results: GetSmartReplyResultsSchema
